const RULES_CATALOG = {
  "en": "<h2 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-bottom: 12px; font-size: 1.3rem;\">ALLIANCE: THE BOARD GAME RULEBOOK</h2>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><em>(A Tabletop Strategy Game of Spatial Positioning, Resource Secrecy, and Diplomatic Accord)</em></p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">1. Introduction & Overview</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><strong>ALLIANCE</strong> is an asynchronous social-strategy tabletop game played on an open coordinate grid. Players navigate the board, manage scarce daily Action Points (AP), forge trust-based alliances, transfer energy across interaction lines, and balance personal victory against collective peace.</p>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Every match operates on clear, deterministic rules: spatial movement and range are mathematically defined, while game tension arises entirely from incomplete knowledge, hidden reserves, and the delicate nature of human trust.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">2. The Three Paths to Victory</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">A game of Alliance concludes in exactly one of three ways:</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Sole Survivor (Last Player Standing):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Play proceeds until only one active player remains on the board. That player is declared the sole victor.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>The Peace Accord (Diplomatic Conference):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">When players convene a formal diplomatic conference, all active participants vote on whether to conclude the game together.</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Unanimous Accord (All Agree):</strong> If every active player votes in favor of peace, the game ends in a shared <strong>Collective Victory</strong> for all survivors.</li>\n<li><strong>Dissent & Betrayal:</strong> If one or more players reject the accord (or abstain), the conference collapses. Depending on the rules chosen for the match, dissent triggers one of three outcomes:</li>\n<li><strong>Betrayal Victory:</strong> The dissenter (or faction of dissenters) exploits the goodwill of other players to claim an immediate victory.</li>\n<li><strong>Bonus AP & Resume Play:</strong> Dissenters receive bonus Action Points, and normal play immediately resumes.</li>\n<li><strong>Resume Play:</strong> The conference dissolves without bonuses, and play resumes immediately.</li>\n</ul>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Inactivity Timeout (Stagnation):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">If no movement or actions occur across the grid before the inactivity deadline expires, the match concludes in an automatic draw (or sudden death grid shrink, if configured).</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">3. Components & Board Setup</h3>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">3.1 The Grid</h4>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li>The board is a rectangular grid divided into coordinate squares.</li>\n<li>Horizontal columns are identified by letters and vertical rows by numbers.</li>\n<li><strong>Stacking Rule:</strong> Exactly one player per square. A player cannot enter an occupied square, nor can they leap or pass through another player during movement.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">3.2 Player Tokens</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Each player on the board is represented by:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Username:</strong> The player's unique name.</li>\n<li><strong>Emblem / Flag:</strong> A national or custom banner (such as United Nations, Finland, Pride, Checkered Flag, or Peace Flag).</li>\n<li><strong>Avatar:</strong> An optional custom portrait or flag fallback.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">3.3 Initial Placement</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">At the start of a match, each registered player is placed onto a randomly selected, unoccupied square on the grid.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">4. Hearts & The Action Economy</h3>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">4.1 Hearts (Resilience)</h4>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Starting Hearts:</strong> Players begin with <strong>3 Hearts</strong> (configurable from 1 to 10).</li>\n<li><strong>Taking Damage:</strong> Each successful strike landed by an opponent removes 1 Heart.</li>\n<li><strong>Elimination:</strong> When a player's Hearts reach 0, they are eliminated from active play and marked with an `[X]`. Eliminated players cannot move, strike, or transfer points.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">4.2 Action Points (AP)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Action Points are the energy currency required to perform actions on the board.</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Starting AP:</strong> Players begin with <strong>0 AP</strong> (configurable from 0 to 10).</li>\n<li><strong>The Daily Drop:</strong> Every 24 hours at the scheduled server drop time (default: <strong>22:00:00</strong>), every active player receives <strong>+1 AP</strong> (configurable).</li>\n<li><strong>Opening Grace Period:</strong> Matches may feature a delay before the first AP distribution. This grants players time to study the board, establish communications, and negotiate initial agreements before active moves begin.</li>\n<li><strong>Banking AP:</strong> Unspent Action Points accumulate indefinitely with no upper limit.</li>\n<li><strong>Elimination Forfeit:</strong> When a player is eliminated, all their banked AP is removed from the game; resources cannot be looted from eliminated players.</li>\n</ul>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">5. Player Actions Reference</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Active players may spend their banked Action Points at any time to execute the following actions:</p>\n<div class=\"rules-table-wrap\" style=\"overflow-x: auto; margin: 12px 0;\"><table class=\"admin-table\" style=\"width: 100%; border-collapse: collapse; font-size: 0.86rem;\"><thead><tr style=\"background: rgba(0, 240, 255, 0.08); border-bottom: 2px solid var(--primary-cyan);\"><th style=\"padding: 8px 10px; text-align: left; color: var(--primary-cyan);\">Action</th><th style=\"padding: 8px 10px; text-align: center; color: var(--primary-cyan);\">Cost</th><th style=\"padding: 8px 10px; text-align: left; color: var(--primary-cyan);\">Target</th><th style=\"padding: 8px 10px; text-align: left; color: var(--primary-cyan);\">Rules &amp; Limitations</th></tr></thead><tbody><tr style=\"border-bottom: 1px solid var(--border-subtle);\"><td style=\"padding: 8px 10px; font-weight: bold; color: var(--matrix-mint);\">MOVE</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">1 AP</td><td style=\"padding: 8px 10px;\">Adjacent Square</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Move 1 square orthogonally: North (▲), South (▼), East (►), or West (◄). Diagonal movement is prohibited. Target square must be unoccupied and within grid boundaries.</td></tr><tr style=\"border-bottom: 1px solid var(--border-subtle);\"><td style=\"padding: 8px 10px; font-weight: bold; color: var(--accent-magenta);\">STRIKE</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">1 AP</td><td style=\"padding: 8px 10px;\">Player in Range</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Challenge another player within your interaction range. Removes 1 Heart from target. Intervening players do not block line of effect.</td></tr><tr style=\"border-bottom: 1px solid var(--border-subtle);\"><td style=\"padding: 8px 10px; font-weight: bold; color: var(--primary-cyan);\">GIFT / TRANSFER AP</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">1 AP</td><td style=\"padding: 8px 10px;\">Player in Range</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Transfer 1 Action Point to a player within your interaction range. By default, zero fee: 1 AP is deducted from your balance and 1 AP credited to recipient.</td></tr><tr><td style=\"padding: 8px 10px; font-weight: bold; color: var(--energy-amber);\">UPGRADE RANGE</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">2 AP</td><td style=\"padding: 8px 10px;\">Self</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Permanently widens your interaction range by +1 tier. Upgrades stack indefinitely.</td></tr></tbody></table></div>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Command Batches & Instant Play</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Players may issue orders in two convenient ways:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Instant Execution:</strong> Actions are applied immediately as you click destinations, targets, or range upgrades.</li>\n<li><strong>Command Batching:</strong> Actions can be planned into a sequence (up to the room's Burst Cap, default 3 AP) and executed together as a single atomic batch.</li>\n</ul>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">6. Interaction Range Geometry</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">All strikes and AP gifts require the target to be inside your <strong>Interaction Range</strong>.</p>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Other players do <strong>not</strong> block line of effect: you may strike or transfer energy across intervening players, as long as the target square falls within your range perimeter.</p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Mathematical Perimeter</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">For a player at square $P$ with Range Level $L$ (starting at Level 1):</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Core Square:</strong> A square of radius $R = L + 1$, spanning $(2L + 3) \\times (2L + 3)$ squares centered on $P$.</li>\n<li><strong>Cardinal Spikes:</strong> 4 orthogonal spikes extending 1 square further in each cardinal direction (North, South, East, West) at distance $R + 1 = L + 2$.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Level 1 Range Perimeter (Starting Base)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">At Level 1, the core square has radius 2 (a 5×5 box), with cardinal spikes at distance 3:</p>\n<div style=\"background: rgba(0,0,0,0.5); border: 1px solid var(--border-subtle); padding: 12px; border-radius: 6px; font-family: var(--font-mono); font-size: 0.8rem; margin: 10px 0;\"><pre style=\"margin: 0; color: var(--matrix-mint); line-height: 1.25;\">- - - x - - -\n- x x x x x -\n- x x x x x -\nx x x P x x x\n- x x x x x -\n- x x x x x -\n- - - x - - -</pre></div>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><em>Legend: `P` = Your Position, `x` = Targetable Square in Range, `-` = Out of Range.</em></p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Level 2 Range Perimeter (First Upgrade)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">At Level 2, the core square expands to radius 3 (a 7×7 box), with cardinal spikes at distance 4:</p>\n<div style=\"background: rgba(0,0,0,0.5); border: 1px solid var(--border-subtle); padding: 12px; border-radius: 6px; font-family: var(--font-mono); font-size: 0.8rem; margin: 10px 0;\"><pre style=\"margin: 0; color: var(--matrix-mint); line-height: 1.25;\">- - - - x - - - -\n- x x x x x x x -\n- x x x x x x x -\n- x x x x x x x -\nx x x x P x x x x\n- x x x x x x x -\n- x x x x x x x -\n- x x x x x x x -\n- - - - x - - - -</pre></div>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Level 3 and Beyond</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Each subsequent upgrade widens the core box by +1 square in all directions and pushes the cardinal spikes 1 step further outward.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">7. Fog of War & Concealed Action</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Information on the board is divided into public and confidential layers:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Public Information:</strong> Board boundaries, player coordinates, elimination announcements, and the room's audit log are visible to everyone.</li>\n<li><strong>Confidential Information:</strong> Exact remaining Hearts, banked Action Points, and upgraded Range levels of other players remain secret.</li>\n<li><strong>Concealed Strikes (Unknown Attacker):</strong>  </li>\n</ul>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">When a player is struck but survives (a non-lethal hit), they receive a private notification that they took 1 damage and see their own remaining Hearts. However, <strong>the attacker's identity is completely concealed</strong>. The attacker learns that their strike connected, but does not see the defender's remaining Hearts.</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Elimination Notice:</strong>  </li>\n</ul>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Only when a player is eliminated (reduced to 0 Hearts) is the decisive hit announced: the eliminated player receives a private receipt revealing who eliminated them, and a public announcement is posted to the room ledger.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">8. The Diplomatic Conference</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">The Diplomatic Conference provides an official forum to resolve the game through negotiation and mutual agreement rather than mutual elimination.</p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.1 Convening the Conference</h4>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li>Active players call for a conference by casting an accord petition. Petitions may be toggled or withdrawn at any time before the threshold is reached.</li>\n<li>When the petition tally reaches the configured <strong>Conference Trigger Threshold</strong> (default: 100% of active players), the conference formally opens.</li>\n<li>Hosts may choose to mask petition counts prior to convening to keep diplomatic intentions private.</li>\n</ol>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.2 Deliberations, Voting & Resolution Timing</h4>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li>When the conference convenes, a deliberation countdown timer begins (default: 120 seconds; configurable from 15 seconds to multiple hours).</li>\n<li>Each active player receives two ballot choices: <strong>AGREE</strong> (ratify the peace accord) or <strong>REJECT</strong> (refuse the accord).</li>\n<li>Players may freely discuss and coordinate during the open countdown.</li>\n<li><strong>Resolution Timing Rule (Conclusion Trigger):</strong> Match hosts can specify whether the conference concludes as soon as every active player has cast a ballot, or remains open strictly until the countdown timer expires (allowing players to adjust ballots and negotiate right up to the final second).</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.3 The Treaty Ratification Rule (Silence is Not Consent)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><strong>Abstentions count as Dissent.</strong></p>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">If a player fails to cast a ballot before the countdown window expires, their silence is officially recorded as dissenting. A collective peace victory requires the active, conscious agreement of every living player.</p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.4 Conference Outcomes</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">When the countdown ends, ballots are evaluated:</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Unanimous Accord (All Agree):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Every active player agreed to peace. The game concludes immediately with all survivors sharing a <strong>Collective Victory</strong>.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Single Dissenter (Exactly 1 Disagrees):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Exactly one player voted against peace or abstained. The conference collapses, enacting the match's configured single-dissenter rule:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Solo Betrayal Victory:</strong> The lone holdout wins the game alone.</li>\n<li><strong>Grant Bonus AP & Resume:</strong> The lone holdout receives an AP bonus (e.g. +3 AP), and active play resumes.</li>\n<li><strong>Resume Play:</strong> Normal play resumes without bonuses.</li>\n</ul>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Multiple Dissenters (2 or More Disagree):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Two or more players voted against peace or abstained. The conference collapses, enacting the match's configured multi-dissenter rule:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Dissenters Share Betrayal Victory:</strong> The dissenting players share a collective victory.</li>\n<li><strong>Grant Bonus AP & Resume:</strong> Each dissenting player receives bonus AP (e.g. +2 AP), and active play resumes.</li>\n<li><strong>Resume Play:</strong> Normal play resumes without bonuses.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.5 Transparency Modes</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">The transparency mode determines what information is visible during deliberations:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Reveal Counts at Conclusion (Default):</strong> Ballots remain private during voting; total counts for and against are published when the conference ends.</li>\n<li><strong>Show How Each Player Votes:</strong> Every player's vote is displayed in real-time as it is cast.</li>\n<li><strong>Show Total Number Who Agreed:</strong> The running tally of agreeing votes is visible, but individual choices remain private.</li>\n<li><strong>Keep Secret Throughout & Resolve Directly:</strong> Ballots and counts remain private throughout, revealing only the final resolution.</li>\n</ul>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">9. Strategic Considerations</h3>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Range vs. Mobility:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Spending 2 AP to upgrade your range gives you extended reach without moving, allowing you to influence more of the board. However, spending AP on range temporarily leaves you with less energy for movement and strikes compared to an active neighbor.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>The Hidden Reserve:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Because Action Points are confidential, an opponent never knows whether you have 0 AP or enough for a multi-action sequence. The mere possibility of a rapid response is a powerful diplomatic deterrent.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Concealed Strikes:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Because non-lethal strikes do not reveal who made them, a player with sufficient range can strike between two rivals, creating uncertainty and shifting dynamics without exposing themselves.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>The Trust Dilemma:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">When betrayal victory is enabled, convening a conference tests every relationship. If all but one player vote for peace in good faith while one secretly dissents, that dissenter takes the victory. Alliances require genuine coordination and careful observation.</p>",
  "ru": "<h2 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-bottom: 12px; font-size: 1.3rem;\">ALLIANCE: ПРАВИЛА НАСТОЛЬНОЙ СТРАТЕГИИ</h2>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><em>(Руководство по позиционной игре, управлению скрытыми ресурсами и дипломатическому согласию)</em></p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">1. Введение и концепция игры</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><strong>ALLIANCE</strong> — это пошагово-асинхронная социально-стратегическая игра на едином координатном поле. Игроки перемещаются по сетке, копят ежедневные очки действий (AP), выстраивают доверительные союзы, передают энергию соседям и балансируют между единоличной победой и общим мирным договором.</p>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Каждый матч подчиняется математически строгим и прозрачным правилам: механики передвижения и радиуса действия полностью детерминированы. Вся глубина партии рождается из неполноты информации, секретности ресурсов и психологии взаимного доверия.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">2. Три пути к победе</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Партия в Alliance завершается ровно одним из трёх способов:</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Единственный выживший (Last Player Standing):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Игра продолжается до тех пор, пока на поле не останется единственный активный игрок. Он объявляется единоличным победителем.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Мирный договор (Дипломатическая конференция):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Когда игроки созывают официальную конференцию, открывается голосование о завершении игры общим миром:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Единогласный мир (Все «За»):</strong> Если каждый оставшийся игрок голосует за мир, все выжившие участники разделяют общую <strong>Коллективную победу</strong>.</li>\n<li><strong>Разногласие и предательство:</strong> Если один или несколько игроков голосуют против мира (или воздерживаются), конференция срывается, запуская одно из трёх правил, выбранных для матча:</li>\n<li><strong>Победа предателя:</strong> Несогласный игрок (или группа несогласных) забирает победу, воспользовавшись миролюбием остальных.</li>\n<li><strong>Бонусные AP и продолжение:</strong> Несогласные получают приток дополнительных очков действий, после чего игра сразу же продолжается.</li>\n<li><strong>Продолжение игры:</strong> Конференция аннулируется без начисления бонусов, и обычная игра продолжается.</li>\n</ul>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Завершение по неактивности (Stagnation):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Если в течение заданного срока на поле не происходит перемещений или результативных действий, партия завершается автоматической ничьей (либо запускается постепенное сжатие границ поля).</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">3. Компоненты и подготовка к игре</h3>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">3.1 Игровое поле</h4>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li>Поле представляет собой прямоугольную сетку из квадратных клеток.</li>\n<li>Столбцы обозначаются буквами, строки — числами.</li>\n<li><strong>Правило вместимости:</strong> Строго один игрок на клетку. Нельзя перемещаться на занятую клетку, перепрыгивать или проходить сквозь других участников.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">3.2 Фишки игроков</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Каждый игрок представлен на поле тремя элементами:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Имя игрока (Username):</strong> Уникальный идентификатор.</li>\n<li><strong>Флаг или эмблема:</strong> Символ страны или персональный значок (например, флаг ООН, Финляндии, Радужный флаг, Клетчатый флаг или Белый флаг мира).</li>\n<li><strong>Аватар:</strong> Загруженное изображение либо отображение флага.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">3.3 Начальное размещение</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">В начале матча каждый участник случайным образом размещается на свободной клетке поля. Два игрока никогда не появляются на одной клетке.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">4. Жизни (Сердца) и экономика очков действий (AP)</h3>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">4.1 Сердца (HP)</h4>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Стартовый запас:</strong> Игроки начинают с <strong>3 Сердцами</strong> (настраивается от 1 до 10).</li>\n<li><strong>Получение урона:</strong> Каждый успешный удар снимает 1 Сердце.</li>\n<li><strong>Выбывание:</strong> При потере всех Сердец (0 HP) игрок выбывает из партии и помечается значком `[X]`. Выбывшие игроки не могут двигаться, наносить удары или передавать очки.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">4.2 Очки действий (AP)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Очки действий — единственный энергетический ресурс для всех действий на поле.</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Стартовый баланс:</strong> Игроки начинают с <strong>0 AP</strong> (настраивается от 0 до 10).</li>\n<li><strong>Ежедневное начисление:</strong> Каждые 24 часа в установленное серверное время (по умолчанию: <strong>22:00:00</strong>) каждый активный игрок получает <strong>+1 AP</strong> (настраивается).</li>\n<li><strong>Пауза на старте:</strong> В матче может быть задан начальный период до первого начисления очков. Это даёт участникам время осмотреться на поле, наладить контакт и обсудить планы до начала активных действий.</li>\n<li><strong>Накопление:</strong> Неизрасходованные очки сохраняются без ограничений по времени и объёму.</li>\n<li><strong>Сгорание при выбывании:</strong> При выбывании игрока все его накопленные очки действий сгорают и удаляются из игры; забрать очки у выбывшего нельзя.</li>\n</ul>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">5. Доступные действия</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Активные игроки могут тратить накопленные очки действий в любой момент:</p>\n<div class=\"rules-table-wrap\" style=\"overflow-x: auto; margin: 12px 0;\"><table class=\"admin-table\" style=\"width: 100%; border-collapse: collapse; font-size: 0.86rem;\"><thead><tr style=\"background: rgba(0, 240, 255, 0.08); border-bottom: 2px solid var(--primary-cyan);\"><th style=\"padding: 8px 10px; text-align: left; color: var(--primary-cyan);\">Действие</th><th style=\"padding: 8px 10px; text-align: center; color: var(--primary-cyan);\">Стоимость</th><th style=\"padding: 8px 10px; text-align: left; color: var(--primary-cyan);\">Цель</th><th style=\"padding: 8px 10px; text-align: left; color: var(--primary-cyan);\">Правила и ограничения</th></tr></thead><tbody><tr style=\"border-bottom: 1px solid var(--border-subtle);\"><td style=\"padding: 8px 10px; font-weight: bold; color: var(--matrix-mint);\">ДВИЖЕНИЕ (MOVE)</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">1 AP</td><td style=\"padding: 8px 10px;\">Соседняя клетка</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Сделать 1 шаг по ортогонали: Север (▲), Юг (▼), Восток (►) или Запад (◄). Ход по диагонали запрещён. Клетка должна быть свободна и находиться в пределах поля.</td></tr><tr style=\"border-bottom: 1px solid var(--border-subtle);\"><td style=\"padding: 8px 10px; font-weight: bold; color: var(--accent-magenta);\">УДАР (STRIKE)</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">1 AP</td><td style=\"padding: 8px 10px;\">Игрок в радиусе</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Атаковать соперника в пределах вашего текущего радиуса. Снимает 1 Сердце цели. Другие игроки не блокируют линию удара.</td></tr><tr style=\"border-bottom: 1px solid var(--border-subtle);\"><td style=\"padding: 8px 10px; font-weight: bold; color: var(--primary-cyan);\">ПОДАРОК / ПЕРЕДАЧА AP</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">1 AP</td><td style=\"padding: 8px 10px;\">Игрок в радиусе</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Передать 1 очко действия игроку в зоне вашего радиуса. По умолчанию комиссия отсутствует: с вас списывается 1 AP, а получатель приобретает 1 AP.</td></tr><tr><td style=\"padding: 8px 10px; font-weight: bold; color: var(--energy-amber);\">УЛУЧШИТЬ РАДИУС</td><td style=\"padding: 8px 10px; text-align: center; font-family: var(--font-mono); color: var(--energy-amber);\">2 AP</td><td style=\"padding: 8px 10px;\">На себя</td><td style=\"padding: 8px 10px; color: var(--text-secondary);\">Навсегда увеличивает радиус взаимодействия на +1 уровень. Улучшения суммируются.</td></tr></tbody></table></div>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Мгновенный режим и пакеты команд</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Отдавать распоряжения можно двумя способами:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Мгновенное применение:</strong> Действие отправляется и исполняется сразу при клике на соседнюю клетку, двойном клике по игроку или кнопке улучшения.</li>\n<li><strong>Пакетная очередь:</strong> Несколько действий планируются заранее в цепочку (до установленного лимита пакета, по умолчанию 3 AP) и выполняются вместе единым залпом.</li>\n</ul>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">6. Геометрия радиуса взаимодействия</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Все удары и передача очков требуют нахождения цели внутри вашего <strong>Радиуса взаимодействия</strong>.</p>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Другие игроки <strong>не загораживают</strong> видимость: вы можете наносить удары и передавать AP поверх других участников, если цель находится в пределах вашего периметра.</p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Математическая зона радиуса</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Для игрока на клетке $P$ с уровнем радиуса $L$ (начиная с 1-го уровня):</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Центральный квадрат:</strong> Сплошной квадрат радиуса $R = L + 1$, размером $(2L + 3) \\times (2L + 3)$ клеток с центром в $P$.</li>\n<li><strong>Ортогональные лучи:</strong> 4 выступа, выдвигающихся ещё на 1 клетку в четырёх направлениях (Север, Юг, Восток, Запад) на дистанции $R + 1 = L + 2$.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Схема радиуса 1-го уровня (Базовый)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">На 1-м уровне центральный квадрат имеет радиус 2 (размер 5×5), а лучи выдвинуты на дистанцию 3:</p>\n<div style=\"background: rgba(0,0,0,0.5); border: 1px solid var(--border-subtle); padding: 12px; border-radius: 6px; font-family: var(--font-mono); font-size: 0.8rem; margin: 10px 0;\"><pre style=\"margin: 0; color: var(--matrix-mint); line-height: 1.25;\">- - - x - - -\n- x x x x x -\n- x x x x x -\nx x x P x x x\n- x x x x x -\n- x x x x x -\n- - - x - - -</pre></div>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><em>Условные обозначения: `P` — ваша позиция, `x` — клетка в зоне досягаемости, `-` — вне зоны.</em></p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">Схема радиуса 2-го уровня (Первое улучшение)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">На 2-м уровне центральный квадрат расширяется до радиуса 3 (размер 7×7), а лучи выдвигаются на дистанцию 4:</p>\n<div style=\"background: rgba(0,0,0,0.5); border: 1px solid var(--border-subtle); padding: 12px; border-radius: 6px; font-family: var(--font-mono); font-size: 0.8rem; margin: 10px 0;\"><pre style=\"margin: 0; color: var(--matrix-mint); line-height: 1.25;\">- - - - x - - - -\n- x x x x x x x -\n- x x x x x x x -\n- x x x x x x x -\nx x x x P x x x x\n- x x x x x x x -\n- x x x x x x x -\n- x x x x x x x -\n- - - - x - - - -</pre></div>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">3-й уровень и далее</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Каждое следующее улучшение расширяет центральный квадрат на +1 клетку во всех направлениях и продлевает ортогональные лучи ещё на 1 шаг.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">7. Туман неизвестности и скрытые действия</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Информация на поле разделена на открытую и конфиденциальную:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Открытая информация:</strong> Границы карты, текущие координаты всех игроков, сообщения об окончательном выбывании и журнал аудита настроек.</li>\n<li><strong>Скрытая информация:</strong> Точное количество Сердец, накопленные очки AP и уровни радиуса других игроков держатся в секрете.</li>\n<li><strong>Скрытые удары (Неизвестный источник):</strong>  </li>\n</ul>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Когда игрок получает урон, но остаётся в игре (нефатальный удар), он получает личное уведомление о потере 1 Сердца и видит свой остаток жизней. Однако <strong>личность нападавшего остаётся полностью скрытой</strong>. Нападающий узнаёт лишь то, что удар был точен, но не видит, сколько Сердец осталось у защитника.</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Сообщение о выбывании:</strong>  </li>\n</ul>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Только когда игрок окончательно выбывает (0 Сердец), наносится решающий удар: выбывший узнаёт имя того, кто его устранил, в личном отчёте, а в общем журнале комнаты публикуется публичное объявление.</p>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">8. Дипломатическая конференция</h3>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Дипломатическая конференция — официальный механизм завершения игры путём переговоров и согласия участников.</p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.1 Созыв конференции</h4>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li>Активные игроки подают петицию о мире. Свой голос можно отозвать в любой момент до созыва конференции.</li>\n<li>Когда доля поданных петиций достигает установленного порога (по умолчанию: 100% активных игроков), конференция открывается.</li>\n<li>Организатор комнаты может скрыть счётчик петиций, чтобы игроки не могли заранее считывать намерения друг друга.</li>\n</ol>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.2 Ход конференции и условие завершения</h4>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li>После открытия конференции запускается таймер обсуждения (по умолчанию: 120 секунд; настраивается от 15 секунд до нескольких часов).</li>\n<li>Каждый активный участник получает два варианта бюллетеня: <strong>СОГЛАСЕН</strong> (подписать мирный договор) или <strong>ПРОТИВ</strong> (отклонить договор).</li>\n<li>В течение времени на таймере игроки могут открыто общаться в чате и согласовывать решение.</li>\n<li><strong>Условие завершения голосования:</strong> Организатор матча может настроить, подводится ли итог сразу, как только все активные игроки отдадут свои голоса, либо окно конференции остаётся открытым строго до истечения таймера (что даёт возможность менять свой выбор и вести дипломатические манёвры до последней секунды).</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.3 Правило ратификации (Молчание — не знак согласия)</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\"><strong>Воздержавшиеся считаются голосующими против.</strong></p>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Если игрок не отправил свой голос до истечения таймера, его голос автоматически засчитывается как отказ от мира. Для коллективной победы требуется осознанное согласие каждого живого участника.</p>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.4 Итоги конференции</h4>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">По истечении времени голоса подсчитываются:</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Единогласный мир (Все «За»):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Все активные игроки согласились на перемирие. Партия мгновенно завершается общей <strong>Коллективной победой</strong> всех выживших.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Один несогласный (Ровно 1 «Против»):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Ровно один участник проголосовал против мира (или воздержался). Конференция срывается, запуская выбранное правило:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Победа предателя:</strong> Одиночный раскольник забирает победу единолично.</li>\n<li><strong>Бонусные AP и продолжение:</strong> Одиночный раскольник получает бонусные AP (например, +3 AP), и игра продолжается.</li>\n<li><strong>Продолжение игры:</strong> Игра возобновляется в обычном режиме без бонусов.</li>\n</ul>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Несколько несогласных (2 и более «Против»):</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Два или более участника проголосовали против мира (или воздержались). Конференция срывается, запуская выбранное правило:</p>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Коллективная победа несогласных:</strong> Группа несогласных разделяет победу.</li>\n<li><strong>Бонусные AP и продолжение:</strong> Каждый несогласный получает бонусные AP (например, +2 AP), и игра продолжается.</li>\n<li><strong>Продолжение игры:</strong> Игра возобновляется в обычном режиме без бонусов.</li>\n</ul>\n<h4 style=\"color: var(--energy-amber); font-family: var(--font-mono); margin-top: 14px; margin-bottom: 6px; font-size: 0.95rem;\">8.5 Режимы прозрачности конференции</h4>\n<ul style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Раскрыть итоги в конце (По умолчанию):</strong> Во время голосования голоса скрыты; после завершения публикуется общее количество голосов «за» и «против».</li>\n<li><strong>Показывать голос каждого игрока:</strong> Выбор каждого участника виден в реальном времени.</li>\n<li><strong>Показывать число согласных:</strong> Отображается общий счётчик согласившихся без раскрытия имён.</li>\n<li><strong>Тайное голосование без раскрытия:</strong> Бюллетени и числа не раскрываются, объявляется только финальный результат.</li>\n</ul>\n<hr style=\"border: none; border-top: 1px solid var(--border-subtle); margin: 16px 0;\">\n<h3 style=\"font-family: var(--font-display); color: var(--primary-cyan); margin-top: 18px; margin-bottom: 8px; font-size: 1.1rem; border-bottom: 1px solid rgba(0, 240, 255, 0.2); padding-bottom: 4px;\">9. Стратегические советы</h3>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Радиус или подвижность:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Улучшение радиуса за 2 AP позволяет охватить большую площадь поля без необходимости перемещаться. Однако в этот момент у вас остаётся меньше очков на непосредственное движение и удары, чем у активного соседа.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Фактор скрытого запаса:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Поскольку количество очков действий скрыто, соперники никогда не знают, сколько AP у вас на руках: ноль или запас на серию манёвров. Эта неопределённость служит надёжным средством дипломатического сдерживания.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Скрытые удары:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Нефатальные удары не раскрывают личность того, кто их совершил. Игрок с широким радиусом может нанести удар между двумя соседями, создавая взаимное недоверие и не раскрывая собственной позиции.</p>\n<ol style=\"color: var(--text-secondary); margin: 6px 0 6px 20px; line-height: 1.55; font-size: 0.88rem;\">\n<li><strong>Дилемма доверия:</strong>  </li>\n</ol>\n<p style=\"color: var(--text-secondary); margin: 6px 0; font-size: 0.88rem; line-height: 1.5;\">Если в настройках включена победа предателя, созыв конференции становится высшей проверкой на прочность союзов. Если все, кроме одного, честно голосуют за мир, а один решает отказаться или дождаться конца таймера — он забирает победу. Доверие требует надёжных договорённостей и внимания.</p>"
};

const I18N = {
  currentLang: 'en',
  catalog: {},

  getFlagEmoji(codeOrEmoji) {
    if (!codeOrEmoji) return '🇺🇳';
    const val = String(codeOrEmoji).trim();
    const specials = {
      'UN': '🇺🇳', 'FI': '🇫🇮', 'PRIDE': '🏳️‍🌈', 'FINISH': '🏁', 'PIRATE': '🏴‍☠️',
      'PEACE': '🏳️', 'BLACK': '🏴', 'EU': '🇪🇺', 'US': '🇺🇸', 'GB': '🇬🇧',
      'RU': '🇷🇺', 'CN': '🇨🇳', 'DE': '🇩🇪', 'FR': '🇫🇷', 'JP': '🇯🇵',
      'KR': '🇰🇷', 'UA': '🇺🇦', 'CA': '🇨🇦', 'AU': '🇦🇺', 'BR': '🇧🇷',
      'IN': '🇮🇳', 'IT': '🇮🇹', 'ES': '🇪🇸', 'MX': '🇲🇽', 'NL': '🇳🇱',
      'SE': '🇸🇪', 'NO': '🇳🇴', 'PL': '🇵🇱', 'KZ': '🇰🇿', 'BY': '🇧🇾',
      'TR': '🇹🇷', 'SA': '🇸🇦', 'ZA': '🇿🇦', 'AR': '🇦🇷', 'SG': '🇸🇬',
      'CH': '🇨🇭', 'AT': '🇦🇹', 'BE': '🇧🇪', 'DK': '🇩🇰', 'IE': '🇮🇪',
      'NZ': '🇳🇿', 'IL': '🇮🇱', 'GR': '🇬🇷', 'PT': '🇵🇹', 'CZ': '🇨🇿',
      'HU': '🇭🇺', 'RO': '🇷🇴', 'BG': '🇧🇬', 'RS': '🇷🇸', 'HR': '🇭🇷',
      'AE': '🇦🇪', 'EG': '🇪🇬', 'NG': '🇳🇬', 'KE': '🇰🇪', 'CL': '🇨🇱',
      'CO': '🇨🇴', 'VN': '🇻🇳', 'TH': '🇹🇭', 'ID': '🇮🇩', 'MY': '🇲🇾',
      'PH': '🇵🇭', 'IS': '🇮🇸', 'EE': '🇪🇪', 'LV': '🇱🇻', 'LT': '🇱🇹',
      'GE': '🇬🇪', 'AM': '🇦🇲', 'AZ': '🇦🇿', 'UZ': '🇺🇿'
    };
    const upper = val.toUpperCase();
    if (specials[upper]) return specials[upper];
    if (upper.length === 2 && /^[A-Z]{2}$/.test(upper)) {
      try {
        const codePoints = [...upper].map(c => 127397 + c.charCodeAt(0));
        return String.fromCodePoint(...codePoints);
      } catch (_) {}
    }
    return val;
  },

  async init() {
    const saved = localStorage.getItem('alliance_lang');
    const browserLang = (navigator.language && navigator.language.startsWith('ru')) ? 'ru' : 'en';
    this.currentLang = saved || browserLang;

    // Load embedded immediately for zero-lag fallback
    this.catalog = Object.assign({}, EMBEDDED_CATALOGS[this.currentLang] || EMBEDDED_CATALOGS['en']);
    this.applyTranslations();

    // Async attempt to load latest updates from server
    await this.loadCatalog(this.currentLang);
    this.applyTranslations();
  },

  async loadCatalog(lang) {
    try {
      const endpoints = [`/static/locales/${lang}.json`, `/api/i18n/${lang}`];
      for (const ep of endpoints) {
        try {
          const res = await fetch(ep);
          if (res && res.ok) {
            const data = await res.json();
            if (data && Object.keys(data).length > 0) {
              this.catalog = Object.assign({}, EMBEDDED_CATALOGS[lang] || {}, data);
              return;
            }
          }
        } catch (_) {}
      }
    } catch (e) {
      console.warn("Using embedded dictionary fallback");
    }
  },

  async setLanguage(lang) {
    this.currentLang = lang;
    localStorage.setItem('alliance_lang', lang);
    this.catalog = Object.assign({}, EMBEDDED_CATALOGS[lang] || EMBEDDED_CATALOGS['en']);
    this.applyTranslations();

    await this.loadCatalog(lang);
    this.applyTranslations();

    if (window.AllianceApp && typeof window.AllianceApp.onLanguageChange === 'function') {
      window.AllianceApp.onLanguageChange(lang);
    }
  },

  t(key, params = {}) {
    let str = (this.catalog && this.catalog[key]) || (EMBEDDED_CATALOGS.en && EMBEDDED_CATALOGS.en[key]) || key;
    for (const [k, v] of Object.entries(params)) {
      str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), v);
    }
    return str;
  },

  applyTranslations() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      const val = this.t(key);
      if (val !== key) {
        el.textContent = val;
      }
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      el.setAttribute('placeholder', this.t(key));
    });
    this.renderRulesContent();
  },

  renderRulesContent() {
    const el = document.getElementById('rules-content-body');
    if (!el) return;
    const lang = this.currentLang || 'en';
    if (typeof RULES_CATALOG !== 'undefined' && RULES_CATALOG[lang]) {
      el.innerHTML = RULES_CATALOG[lang];
    }
  }
};





